package com.example.rokidgeminisecretary;
import android.content.*;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.file.*;
/** Per-file verified receipts, not a promise that the original remains on glasses. */
final class VerifiedStorage {
 static void recordPhoto(File photo,String id,String sha,int total)throws Exception{AtomicFile f=new AtomicFile(new File(photo.getParentFile(),id+".receipt.gcm"));long received=System.currentTimeMillis();try{JSONObject old=receipt(photo);if(!sha.equals(old.optString("sha"))||total!=old.optInt("bytes"))throw new IOException("受信時の記録と競合しています");received=old.optLong("receivedAt",received);}catch(FileNotFoundException missing){}JSONObject v=new JSONObject().put("id",id).put("sha",sha).put("bytes",total).put("receivedAt",received);FileOutputStream out=null;try{out=f.startWrite();out.write(DeviceSecrets.photos().encrypt(v.toString().getBytes("UTF-8")));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}
 static JSONObject receipt(File photo)throws Exception{return new JSONObject(new String(DeviceSecrets.photos().decrypt(new AtomicFile(new File(photo.getParentFile(),photo.getName().replace(".gcm",".receipt.gcm"))).readFully()),"UTF-8"));}
 static JSONObject photo(Context c,String id)throws Exception{if(!id.matches("[0-9]{13}-[a-f0-9-]{36}"))throw new IOException("写真IDが不正です");File f=new File(RecorderPhotoStore.root(c),id+".gcm");JSONObject out=new JSONObject().put("id",id).put("type","photo").put("exists",f.isFile()).put("at",System.currentTimeMillis());JSONObject expected=null;try{expected=receipt(f);out.put("expectedSha256",expected.getString("sha")).put("receivedAt",expected.optLong("receivedAt"));}catch(FileNotFoundException e){out.put("receiptMissing",true);}catch(Exception e){out.put("receiptUnreadable",true);}if(!f.isFile()){int good=0,bad=0;File[] partial=f.getParentFile().listFiles((d,name)->name.startsWith(id+"-")&&name.endsWith(".part"));if(partial!=null)for(File part:partial)try{int size=RecorderPhotoStore.read(part).length;if(size<1||size>131072)throw new IOException();good++;}catch(Exception e){bad++;}return out.put("partialChunks",good).put("unreadableChunks",bad).put("verified",false).put("message",good+bad>0?"受信途中：確認できた区間 "+good+"、読めない区間 "+bad+"。写真全体の保存は未確認です":"スマホの保存ファイルがありません。元が残る場合だけ再転送できます");}try{byte[] bytes=RecorderPhotoStore.read(f);String hash=RecorderPhotoStore.hash(bytes);return out.put("actualSha256",hash).put("bytes",bytes.length).put("verified",expected!=null&&hash.equals(expected.optString("sha"))&&bytes.length==expected.optInt("bytes")).put("readable",true).put("message",expected==null?"復号できました。旧記録には受信時ハッシュの照合記録がありません":hash.equals(expected.optString("sha"))&&bytes.length==expected.optInt("bytes")?"受信時のサイズ・ハッシュと一致":"受信時の記録と不一致。原本が残る場合は不足だけ再転送できます");}catch(Exception e){return out.put("verified",false).put("readable",false).put("message","復号・保存内容を検証できません。現在のファイルは保持しています");}}
 static JSONArray list(Context c)throws Exception{JSONArray out=new JSONArray();File[] fs=RecorderPhotoStore.root(c).listFiles();if(fs==null)throw new IOException("保存先を取得できません");java.util.Arrays.sort(fs,(a,b)->b.getName().compareTo(a.getName()));for(File f:fs)if(f.getName().matches("[0-9]{13}-[a-f0-9-]{36}\\.gcm")&&out.length()<100)out.put(new JSONObject().put("id",f.getName().replace(".gcm","")).put("type","photo").put("title",f.getName().substring(0,13)));java.util.HashSet<String> partialIds=new java.util.HashSet<>();for(File candidate:fs){String name=candidate.getName();if(name.endsWith(".part")&&name.length()>116){String id=name.substring(0,50);if(id.matches("[0-9]{13}-[a-f0-9-]{36}")&&!new File(candidate.getParentFile(),id+".gcm").exists()&&partialIds.size()<20&&partialIds.add(id))out.put(new JSONObject().put("id",id).put("type","photo").put("title",id.substring(0,13)+" / 受信途中"));}}JSONArray meetings=MeetingAudioStore.list(c);for(int i=0;i<Math.min(50,meetings.length());i++){JSONObject m=meetings.getJSONObject(i);out.put(new JSONObject().put("id",m.getString("id")).put("type","meeting").put("title",m.optString("title")).put("parts",m.optInt("parts")));}return out;}
 static JSONObject checkPhoto(Context c,JSONObject input)throws Exception{String id=input.getString("id"),sha=input.getString("sha");int total=input.getInt("total");if(!id.matches("[0-9]{13}-[a-f0-9-]{36}")||!sha.matches("[a-f0-9]{64}")||total<4||total>8000000)throw new IOException("照合対象が不正です");if(c.getSharedPreferences("recorder_photo_deletions",0).getBoolean(id,false))return new JSONObject().put("ok",true).put("deleted",true).put("complete",true).put("id",id).put("sha",sha).put("total",total);File root=RecorderPhotoStore.root(c),target=new File(root,id+".gcm");if(target.isFile()){try{JSONObject verified=RecorderPhotoStore.receipt(target,id,sha,total);RecorderPhotoStore.metadata(root,id,input);return verified;}catch(Exception invalid){if(!sha.equals(c.getSharedPreferences("storage_repairs",0).getString(id,""))||c.getSharedPreferences("storage_repairs",0).getLong(id+"-expires",0)<System.currentTimeMillis())return new JSONObject().put("ok",false).put("error","スマホの既存ファイルと不一致。保存確認画面から修復を明示してください");File quarantine=new File(root,id+".quarantine-"+java.util.UUID.randomUUID());Files.move(target.toPath(),quarantine.toPath());}}RecorderPhotoStore.metadata(root,id,input);JSONArray offsets=new JSONArray();for(int offset=0;offset<total;offset+=131072){File part=new File(root,id+"-"+sha+"-"+offset+".part");try{if(part.isFile()&&RecorderPhotoStore.read(part).length==Math.min(131072,total-offset))offsets.put(offset);}catch(Exception invalid){}}if(offsets.length()==(total+131071)/131072){JSONArray retry=new JSONArray();for(int i=0;i<offsets.length()-1;i++)retry.put(offsets.get(i));offsets=retry;}return new JSONObject().put("ok",true).put("offsets",offsets).put("complete",false);}
 static JSONObject queuePhotoRepair(Context c,String id)throws Exception{JSONObject check=photo(c,id);if(check.optBoolean("verified"))throw new IOException("すでに検証済みです");if(c.getSharedPreferences("recorder_photo_deletions",0).getBoolean(id,false))throw new IOException("削除済み写真は復活させません");String expected=check.optString("expectedSha256");if(!expected.isEmpty()&&!c.getSharedPreferences("storage_repairs",0).edit().putString(id,expected).putLong(id+"-expires",System.currentTimeMillis()+120000).commit())throw new IOException("修復の対象を保存できません");JSONObject command=new JSONObject().put("ids",new JSONArray().put(id)).put("expiresAt",System.currentTimeMillis()+120000);if(!MainActivity.queueBridgeCommand(c,"__LOKI_STORAGE_REPAIR__:"+command,false))throw new IOException("送信待ちが満杯です");return new JSONObject().put("queued",true).put("message","元のグラスに残る対象だけ再転送を依頼しました。原本が残っていなければ復元できません。削除済み写真は対象外です");}
 private VerifiedStorage(){}
}
